MagickBooleanType SkipMipmapImages(Image* image, DDSInfo* dds_info, int pixel_size, ExceptionInfo* exception) {
  if (!image || !dds_info || !exception) {
    return MagickFalse;
  }

  if (!dds_info->has_mipmap || (image->columns <= 0 || image->rows <= 0)) {
    return MagickTrue;
  }

  MagickSizeType width = (MagickSizeType)image->columns;
  MagickSizeType height = (MagickSizeType)image->rows;

  for (MagickSizeType level = 1; level < dds_info->mipmap_levels; level++) {
    MagickSizeType level_width = width / 2;
    MagickSizeType level_height = height / 2;

    if (level_width < 1) {
      level_width = 1;
    }
    if (level_height < 1) {
      level_height = 1;
    }

    MagickSizeType level_size = level_width * level_height * pixel_size;

    if (level_size > (MagickSizeType)SIZE_MAX) {
      (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "MemoryAllocationFailed", "Unable to skip mipmap images");
      return MagickFalse;
    }

    if (SeekImage(image, (size_t)level_size, SEEK_CUR) != (size_t)level_size) {
      (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "SeekFailed", "Unable to skip mipmap images");
      return MagickFalse;
    }

    width = level_width;
    height = level_height;
  }

  return MagickTrue;
}
